<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class PurchaseOrder extends Model { protected $fillable=['number','rfq_id','quotation_id','vendor_id','created_by','issued_at','delivery_date','total','payment_terms','status','authorization_note']; protected $casts=['issued_at'=>'date','delivery_date'=>'date','total'=>'decimal:2']; public function rfq(){return $this->belongsTo(Rfq::class);} public function vendor(){return $this->belongsTo(User::class,'vendor_id');} public function quotation(){return $this->belongsTo(Quotation::class);} public function goodsReceipts(){return $this->hasMany(GoodsReceipt::class,'po_id');} public function invoices(){return $this->hasMany(Invoice::class,'po_id');} }
